/ideas.query:
query Viewer {
  viewer {
    id
    name
    role
    workspaces
  }
}

query Regime {
  regime {
    session
    label
    headline
    unknownReason {
      code
      kind
      guideTerm
      kindText
      cause {
        links {
          level
          subject
          status
          message
          runId
        }
      }
    }
    scores {
      macroRisk {
        value
        unknown {
          code
          kind
          guideTerm
          kindText
          cause {
            links {
              level
              subject
              status
              message
              runId
            }
          }
        }
        feature
        coverageFeature
        threshold
      }
      marketStress {
        value
        unknown {
          code
          kind
          guideTerm
          kindText
          cause {
            links {
              level
              subject
              status
              message
              runId
            }
          }
        }
        feature
        coverageFeature
        threshold
      }
      fragility {
        value
        unknown {
          code
          kind
          guideTerm
          kindText
          cause {
            links {
              level
              subject
              status
              message
              runId
            }
          }
        }
        feature
        coverageFeature
        threshold
      }
    }
    sizing {
      label
      multiplier
      enabled
      unknownMultiplier
      multipliers {
        label
        multiplier
      }
      screeners {
        screenerId
        name
        enabled
        pauseIn
      }
    }
    indicators {
      key
      pace
      plainName
      technicalName
      oneLiner
      whyItMatters
      whatOnMeans
      before {
        episode
        line
      }
      leadTime
      falseAlarms
      links {
        title
        url
      }
      value
      unknown {
        code
        kind
        guideTerm
        kindText
        cause {
          links {
            level
            subject
            status
            message
            runId
          }
        }
      }
      format
      status
      changed
      feature
      verdictFeature
      range {
        min
        max
      }
      threshold
      direction
      how {
        text
        url
      }
    }
  }
}

query IdeasPage($first: Int!, $after: String, $names: [FeatureName!]!, $filters: [FilterInput!]) {
  ideas(first: $first, after: $after, filters: $filters) {
    session
    total
    hasMore
    nextCursor
    facets {
      total
      matched
      items {
        id
        active
        removes
        unknown
        options {
          value
          count
        }
        bins {
          lo
          hi
          count
        }
      }
    }
    pausedTotal
    paused {
      instrumentId
      instrument {
        symbol
      }
      result {
        configId
        score
        reasons
        regime
      }
    }
    screeners {
      screener {
        id
        name
        owner
        version
      }
      run {
        runId
        configVersion
        paused
        coverage
        unavailable {
          kind
          guideTerm
          kindText
        }
      }
      notRun {
        code
        reason
        kind
        guideTerm
        kindText
        cause {
          links {
            level
            subject
            status
            message
            runId
          }
        }
      }
      picked
      withheld
      top {
        instrumentId
        score
        instrument {
          symbol
        }
      }
    }
    items {
      rank
      instrumentId
      score
      regime
      sizeMultiplier
      watchOut
      instrument {
        symbol
        name
        features(names: $names) {
          name
          value
          unknown {
            code
            kind
            guideTerm
            kindText
            cause {
              links {
                level
                subject
                status
                message
                runId
              }
            }
          }
          info {
            format
            unit
            dtype
            nullMeaning
          }
        }
      }
      best {
        configId
        decision
        score
        reasons
        criteria {
          id
          outcome
        }
      }
      pickedBy {
        configId
        own
        position
        score
        decision
      }
      metrics {
        name
        value
      }
    }
  }
}

query FilterSet($surface: String!, $withFeatures: [String!]) {
  filterSet(surface: $surface, withFeatures: $withFeatures) {
    surface
    label
    searchable
    filters {
      id
      label
      group
      kind
      guide
      options {
        value
        label
      }
      bins
      windowUnit
      unit
    }
  }
}

